2.1 一个小Demo
#include &lt;stdio.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/types.h&gt;
#include &lt;stdlib.h&gt;

int main() {
    pid_t pid = 0;
    pid = fork();

    if (pid &lt; 0) {
        printf("Could not create process\n");
        exit(1);
    } else if (pid == 0) {
        sleep(1);
        printf("Hello from the child process\n");
    } else if (pid &gt; 0) {
        printf("Hello from the parent process\n");
    }

    printf("This code will be executed by both the child and parent\n");

    return 0;
}

Hello from the parent process
This code will be executed by both the child and parent

1.1.1 加减乘除
设 \(a = 7\), \(b = 3\)，计算四则运算：

1.1.1.1 代码表示

#include &lt;stdio.h&gt;

int main() {
    int a = 7, b = 3;
    printf("a + b = %d\n", a + b);
    printf("a - b = %d\n", a - b);
    printf("a * b = %d\n", a * b);
    printf("a / b = %d\n", a / b);
    printf("a %% b = %d\n", a % b);
    return 0;
}

a + b = 10
a - b = 4
a * b = 21
a / b = 2
a % b = 1





1.1.2 浮点精度
比较 \(\frac{1}{3}\) 的单精度与双精度表示：

1.1.2.1 代码表示

#include &lt;stdio.h&gt;

int main() {
    float f = 1.0f / 3.0f;
    double d = 1.0 / 3.0;
    printf("float:  %.9f\n", f);
    printf("double: %.15f\n", d);
    return 0;
}

float:  0.333333343
double: 0.333333333333333





1.1.3 勾股定理
验证 \(3^2 + 4^2 = 5^2\)，并计算斜边 \(c = \sqrt{a^2 + b^2}\)：

1.1.3.1 代码表示

#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

int main() {
    double a = 3.0, b = 4.0;
    double c = sqrt(a*a + b*b);
    printf("c = %.6f\n", c);
    return 0;
}

c = 5.000000
